-- T1 writes but has NOT committed. T2 must not see it.
-- T1: BEGIN; UPDATE accounts SET balance = 0 WHERE id = 1;
-- T2: BEGIN; SELECT balance FROM accounts WHERE id = 1; -- still 100
-- T1: COMMIT;
-- T2: SELECT balance FROM accounts WHERE id = 1; -- now 0 (new snapshot)

-- Non-repeatable read is LEGAL here:
-- T2: BEGIN;
-- T2: SELECT balance FROM accounts WHERE id = 1; -- 100
-- T1: BEGIN; UPDATE accounts SET balance = 0 WHERE id = 1; COMMIT;
-- T2: SELECT balance FROM accounts WHERE id = 1; -- 0, same txn, new value
-- T2: COMMIT;

-- Safe write pattern under Read Committed:
-- BEGIN;
-- SELECT balance FROM accounts WHERE id = 1 FOR UPDATE; -- lock it
-- UPDATE accounts SET balance = balance - 60 WHERE id = 1 AND balance >= 60;
-- COMMIT;
